#!/usr/bin/env bash
# Tests for backup-restore.sh and backup-restore-rehearsal.sh: a nightly backup
# set restored into throwaway targets, each artifact proved by a fact, a damaged
# artifact named while the others are still reported, and the encrypted path
# with a throwaway age key.
#
# No Docker needed: the fakes in datastore-fakes.sh. The set is generated by
# fixtures/backup-set/generate.py from a seed (synthetic data); its file facts
# are written by backup.sh's own record_facts. Needs `age` and `age-keygen`
# (CI installs the age package); the test fails when they are missing.
#
# Run: bash deploy/scripts/tests/backup-restore.test.sh

set -euo pipefail

script_dir=$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)
repo_root=$(CDPATH='' cd -- "$script_dir/../.." && pwd)
restore="$script_dir/backup-restore.sh"
rehearsal="$script_dir/backup-restore-rehearsal.sh"
generator="$script_dir/tests/fixtures/backup-set/generate.py"

command -v age > /dev/null && command -v age-keygen > /dev/null \
  || { echo "age and age-keygen are required (apt-get install age); not skipping" >&2; exit 1; }

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
bin="$work/bin"
# shellcheck source=deploy/scripts/tests/datastore-fakes.sh
source "$script_dir/tests/datastore-fakes.sh"
ds_fakes_install "$bin"

failures=0
case_dir=""
set_dir=""
rc=0

fail() {
  echo "  FAIL $1"
  sed 's/^/       /' "$case_dir/out"
  failures=$((failures + 1))
}
check() { if [[ "$2" == "$3" ]]; then echo "  ok   $1"; else fail "$1 (expected '$2', got '$3')"; fi; }
calls() { grep -c -- "$1" "$case_dir/fake/calls" || true; }
count() { grep -c -- "$1" "$case_dir/out" || true; }

# A case: the real compose file (the restore reads every image from it), a
# generated set marked complete, and its file facts from backup.sh.
new_case() {
  case_dir="$work/$1"
  local f="$case_dir/fake"
  mkdir -p "$f/running" "$case_dir/backups"
  : > "$f/calls"
  cp "$repo_root/deploy/docker-compose.yml" "$case_dir/docker-compose.yml"
  echo 1000 > "$f/du_bytes"
  echo 1000000 > "$f/df_avail"
  new_set "${2:-2026-11-12}" "${3:-7}"
}

# new_set <date> <seed>: backups/<date>, complete.
new_set() {
  set_dir="$case_dir/backups/$1"
  python3 "$generator" "$set_dir" "$2"
  (
    export BACKUP_DIR="$set_dir"
    # shellcheck source=deploy/scripts/backup.sh
    source "$script_dir/backup.sh"
    trap - ERR EXIT
    set +e
    for f in "$set_dir"/*.sql "$set_dir"/*.tar.gz "$set_dir"/*.rdb "$set_dir"/*.archive "$set_dir"/*.snapshot; do
      record_facts "$f"
    done
    listing="$(tar -cf - -C "$set_dir" research-uploads | tar -tf - | tar_listing_facts)"
    facts_add "file research-uploads.tar.gz entries ${listing%% *}"
    facts_add "file research-uploads.tar.gz listing ${listing##* }"
  )
  : > "$set_dir/.backup-complete"
}

run_restore() {
  set +e
  PATH="$bin:$PATH" FAKE="$case_dir/fake" KLAI_COMPOSE_DIR="$case_dir" bash "$restore" "$@" > "$case_dir/out" 2>&1
  rc=$?
  set -e
}

run_rehearsal() {
  set +e
  PATH="$bin:$PATH" FAKE="$case_dir/fake" KLAI_COMPOSE_DIR="$case_dir" bash "$rehearsal" > "$case_dir/out" 2>&1
  rc=$?
  set -e
}

events() {
  python3 -c '
import json, sys
for line in open(sys.argv[1]):
    e = json.loads(line)
    print(e["artifact"], e["outcome"])' "$case_dir/logs/auto-rollback.log" 2> /dev/null | paste -sd, -
}

ALL_ARTIFACTS="postgres gitea mongodb redis vexa_redis meilisearch qdrant falkordb garage_meta garage_data firecrawl_postgres listmonk_postgres crm_postgres fider_postgres umami_postgres crm_storage listmonk_uploads scribe_audio research_uploads"

echo "backup-restore.sh"

# --- (a) a complete set: every artifact restored and every fact matches -------
new_case complete
run_restore "$set_dir"
check "complete set -> exit 0" 0 "$rc"
check "  all 19 artifacts restored" "backup restore: 19 ok, 0 failed, 0 skipped" "$(tail -n 1 "$case_dir/out")"
check "  every artifact has its own ok line" "$ALL_ARTIFACTS" "$(sed -n 's/^ok   \([a-z_]*\):.*/\1/p' "$case_dir/out" | paste -sd' ' -)"
check "  postgres: rows of the dump equal the rows restored" 1 "$(count '^ok   postgres: 3 tables with as many rows as the dump holds')"
check "  every throwaway container is on --network none, labelled, limited" 0 "$(grep 'docker run -d' "$case_dir/fake/calls" | grep -vc -- '--network none --label klai.adhoc=datastore-restore --memory 6g --cpus 2' || true)"
check "  nothing mounts a live volume" 0 "$( (grep 'docker run' "$case_dir/fake/calls" | grep -c -- '--volumes-from') || true)"
check "  every container is removed afterwards" yes "$(grep -q 'docker rm -f klai-backup-restore-' "$case_dir/fake/calls" && echo yes || echo no)"
check "  the work directory is removed" "" "$(find "$case_dir/backups" -name '.backup-restore.*')"

# --- (b) damaged artifacts: named, the others still restored ------------------
new_case damaged
head -c 400 "$set_dir/crm-postgres-all.sql" > "$set_dir/crm-postgres-all.sql.cut" && mv "$set_dir/crm-postgres-all.sql.cut" "$set_dir/crm-postgres-all.sql"
head -c 60 "$set_dir/gitea-repos.tar.gz" > "$set_dir/gitea-repos.tar.gz.cut" && mv "$set_dir/gitea-repos.tar.gz.cut" "$set_dir/gitea-repos.tar.gz"
run_restore "$set_dir"
check "a cut dump and a cut tar -> exit 1" 1 "$rc"
check "  the dump is named" 1 "$(count '^FAIL crm_postgres: crm-postgres-all.sql differs from the checksum recorded at backup time')"
check "  the tar is named" 1 "$(count '^FAIL gitea: gitea-repos.tar.gz differs from the checksum recorded at backup time')"
check "  the other 17 are restored and reported" "backup restore: 17 ok, 2 failed, 0 skipped" "$(tail -n 1 "$case_dir/out")"

# A copy whose checksum was re-recorded still fails on what it holds.
new_case damaged_but_recorded
head -c 400 "$set_dir/umami-postgres-all.sql" > "$set_dir/umami.cut" && mv "$set_dir/umami.cut" "$set_dir/umami-postgres-all.sql"
python3 - "$set_dir" <<'PY'
import hashlib, sys
d = sys.argv[1]
lines = open(d + "/backup-facts.txt").read().splitlines()
h = hashlib.sha256(open(d + "/umami-postgres-all.sql", "rb").read()).hexdigest()
lines = [("file umami-postgres-all.sql sha256 " + h) if l.startswith("file umami-postgres-all.sql sha256") else l for l in lines]
open(d + "/backup-facts.txt", "w").write("\n".join(lines) + "\n")
PY
run_restore "$set_dir" umami_postgres
check "a dump cut short but with a matching checksum -> exit 1" "1 1" "$rc $(count '^FAIL umami_postgres: the dump has no end marker')"

new_case replay_fails
touch "$case_dir/fake/pg_replay_fails"
run_restore "$set_dir" postgres
check "a dump the database refuses -> exit 1, named" "1 1" "$rc $(count '^FAIL postgres: psql could not replay the dump')"

# --- explicit names, unknown names, skipped artifacts -------------------------
new_case select
run_restore "$set_dir" redis qdrant
check "two artifacts by name -> only those" "0 redis,qdrant" "$rc $(sed -n 's/^ok   \([a-z_]*\):.*/\1/p' "$case_dir/out" | paste -sd, -)"
run_restore "$set_dir" caddy
check "an unknown artifact -> exit 2" "2 1" "$rc $(count '^FAIL caddy: not an artifact')"

new_case skipped
rm "$set_dir/crm-storage.tar.gz"
sed -i.bak '/crm-storage/d' "$set_dir/backup-facts.txt"
run_restore "$set_dir"
check "an artifact backup.sh recorded nothing for -> skipped, exit 0" "0 backup restore: 18 ok, 0 failed, 1 skipped" "$rc $(tail -n 1 "$case_dir/out")"
run_restore "$set_dir" crm_storage
check "  the same artifact asked for by name -> exit 1" "1 1" "$rc $(count '^FAIL crm_storage: crm-storage.tar.gz is missing')"

new_case lost
rm "$set_dir/garage-meta.tar.gz"
run_restore "$set_dir"
check "a recorded artifact whose file is gone -> exit 1, named" "1 1" "$rc $(count '^FAIL garage_meta: garage-meta.tar.gz is missing')"

new_case no_facts
rm "$set_dir/backup-facts.txt"
run_restore "$set_dir"
check "a set without backup-facts.txt -> exit 1, nothing passes" "1 0" "$rc $(count '^ok ')"

# --- (c) the encrypted set with a throwaway key -------------------------------
new_case encrypted
age-keygen -o "$case_dir/key.txt" 2> /dev/null
age-keygen -o "$case_dir/other-key.txt" 2> /dev/null
recipient="$(age-keygen -y "$case_dir/key.txt")"
mkdir "$case_dir/offsite"
for f in "$set_dir"/*.sql "$set_dir"/*.tar.gz "$set_dir"/*.rdb "$set_dir"/*.archive "$set_dir"/*.snapshot "$set_dir"/backup-facts.txt; do
  age -r "$recipient" "$f" > "$case_dir/offsite/$(basename "$f").age"
done
# As encrypt_artifacts does: the research uploads directory as a tar stream.
tar -czf - -C "$set_dir" research-uploads | age -r "$recipient" > "$case_dir/offsite/research-uploads.tar.gz.age"
run_restore --identity "$case_dir/key.txt" "$case_dir/offsite"
check "the .age set with the right identity -> exit 0, 19 restored" "0 backup restore: 19 ok, 0 failed, 0 skipped" "$rc $(tail -n 1 "$case_dir/out")"
check "  the identity is not printed" 0 "$(grep -c 'AGE-SECRET-KEY' "$case_dir/out" || true)"
check "  no decrypted copy is left behind" "" "$(find "$case_dir" -name 'postgres-all.sql' -not -path "$set_dir/*")"
run_restore --identity "$case_dir/other-key.txt" "$case_dir/offsite"
check "a wrong identity -> exit 1, nothing restored" "1 0" "$rc $(count '^ok ')"
check "  every artifact names the failed decrypt" 19 "$(count '^FAIL [a-z_]*: decrypting .* failed')"
run_restore "$case_dir/offsite"
check ".age files without --identity -> exit 2" "2 1" "$rc $(count 'FAIL set: .* --identity <file> is required')"
head -c 50 "$case_dir/offsite/crm-postgres-all.sql.age" > "$case_dir/offsite/x" && mv "$case_dir/offsite/x" "$case_dir/offsite/crm-postgres-all.sql.age"
run_restore --identity "$case_dir/key.txt" "$case_dir/offsite"
check "one cut .age file -> named, the other 18 restored" "1 1 backup restore" "$rc $(count '^FAIL crm_postgres: decrypting') $(tail -n 1 "$case_dir/out" | cut -d: -f1)"

# --- (d) the rehearsal: a restored fact that differs from the recorded one ----
echo
echo "backup-restore-rehearsal.sh"
new_case rehearsal_ok 2026-11-11 3
new_set 2026-11-12 4
new_set 2026-11-13 5
rm "$case_dir/backups/2026-11-13/.backup-complete"
run_rehearsal
check "newest complete set (not the unfinished newer one) -> exit 0" 0 "$rc"
check "  one ok event per artifact" "$(echo "$ALL_ARTIFACTS" | tr ' ' '\n' | sed 's/$/ ok/' | paste -sd, -)" "$(events)"
check "  it was the 12th" 19 "$(grep -c '"set":"2026-11-12"' "$case_dir/logs/auto-rollback.log")"

new_case rehearsal_fact_mismatch
sed -i.bak 's/^facts redis count keys .*/facts redis count keys 9999/' "$set_dir/backup-facts.txt"
run_rehearsal
check "a recorded key count the restore does not reach -> exit 1" 1 "$rc"
check "  redis is failed with the numbers, the other 18 are ok" "1 18" "$(grep -c '"artifact":"redis","set":"2026-11-12","detail":"[^"]*9999' "$case_dir/logs/auto-rollback.log") $(grep -c '"outcome":"ok"' "$case_dir/logs/auto-rollback.log")"

new_case rehearsal_rows_missing
touch "$case_dir/fake/pg_drops_row"
run_rehearsal
check "a restore with fewer rows than the dump holds -> exit 1, postgres failed" "1 1" "$rc $(grep -c '"outcome":"failed","artifact":"postgres"' "$case_dir/logs/auto-rollback.log")"

new_case rehearsal_mongo_short
touch "$case_dir/fake/mongo_short"
run_rehearsal
check "fewer documents counted than mongorestore reported -> exit 1, mongodb failed" "1 1" "$rc $(grep -c '"outcome":"failed","artifact":"mongodb"' "$case_dir/logs/auto-rollback.log")"

new_case rehearsal_no_set
rm -rf "$case_dir/backups"/2026*
run_rehearsal
check "no complete set -> exit 1 and an event" "1 set failed" "$rc $(events)"

new_case rehearsal_no_disk
echo 1 > "$case_dir/fake/df_avail"
run_rehearsal
check "no room for the restore -> exit 1, nothing started" "1 0" "$rc $(calls 'docker run')"

# --- backup.sh records what the restore compares against ----------------------
echo
echo "backup.sh record_redis_facts"
new_case recording
mkdir -p "$work/recbin"
cat > "$work/recbin/docker" <<'STUB'
#!/usr/bin/env bash
case "$*" in
  *" INFO keyspace") printf '# Keyspace\r\ndb0:keys=60,expires=3,avg_ttl=100\r\ndb1:keys=5,expires=0,avg_ttl=0\r\n' ;;
  *) exit 1 ;;
esac
STUB
chmod +x "$work/recbin/docker"
rec_dir="$work/rec"
mkdir -p "$rec_dir"
(
  export BACKUP_DIR="$rec_dir"
  PATH="$work/recbin:$PATH"
  # shellcheck source=deploy/scripts/backup.sh
  source "$script_dir/backup.sh"
  trap - ERR EXIT
  set +e
  record_redis_facts redis klai-core-redis-1 -a pw
) > "$case_dir/out" 2>&1
check "keys without a TTL are recorded for the redis artifact" "facts redis count keys 62" "$(cat "$rec_dir/backup-facts.txt")"

echo
if [[ "$failures" -eq 0 ]]; then
  echo "backup-restore: all cases passed"
else
  echo "backup-restore: $failures case(s) failed"
  exit 1
fi
